from moler.util.moler_test import MolerTest


class UpdateAndWaitUntilUp(object):
    """Class for config remote update and wait until controllers up."""

    def __init__(self, executor, workstation, ctrls=[]):
        """Config remote update and wait until controllers up.

        :param executor: executor device
        :param ctrls: list of ctrl devices --> each should be class of taf.ul.sc.rtg.controller.Controller
        """
        self._ctrls = [ControllerRebootUtil(ctrl) for ctrl in ctrls]
        self._executor = executor
        self._workstation = workstation
        self.reboot_wait_time = 60
        self.recheck_time = 10

    def config_remote_update_and_wait_until_controllers_up(self):
        """Keyword for restarting controllers.

        :return: None
        """
        for ctrl in self._ctrls:
            if ctrl.connection_type == 'telnet':
                self._start_stopping_session_observer(ctrl)
            elif ctrl.connection_type == 'ssh':
                self._start_ping_no_response_observer(ctrl)

        self._executor.update_remote_configuration()
        MolerTest.sleep(self.reboot_wait_time)
        self._wait_until_controllers_up()
        self._cancel_observers()

    def _start_stopping_session_observer(self, ctrl):
        """Start stopping session observer.

        :param ctrl: Controller on which event will be observed.
        :return: None but start stopping session observer
        """
        ctrl.stopping_session = ctrl.device.get_event(event_name="stopping_session",
                                                      event_params={"till_occurs_times": 1})
        ctrl.stopping_session.add_event_occurred_callback(callback=self._set_controller_to_down,
                                                          callback_params={"ctrl": ctrl})
        ctrl.stopping_session.start()

    def _start_ping_no_response_observer(self, ctrl):
        """Start ping no response observer.

        :param ctrl: Controller on which event will be observed.
        :return: None but start ping no response observer
        """
        ctrl.cmd_ping = self._workstation.device.get_cmd(cmd_name="ping",
                                                         cmd_params={"destination": ctrl.host, "options": "-O"})
        ctrl.ping_no_response = self._workstation.device.get_event(event_name="ping_no_response",
                                                                   event_params={"till_occurs_times": 1})
        ctrl.ping_no_response.add_event_occurred_callback(callback=self._set_controller_to_down,
                                                          callback_params={"ctrl": ctrl})
        ctrl.ping_no_response.start()
        ctrl.cmd_ping.start(timeout=600)

    def _cancel_observers(self):
        """Cancel observers which check if controller starts rebooting.

        :return: None
        """
        for ctrl in self._ctrls:
            if ctrl.connection_type == 'telnet':
                ctrl.stopping_session.cancel()
                ctrl.stopping_session = None
            elif ctrl.connection_type == 'ssh':
                ctrl.ping_no_response.cancel()
                ctrl.ping_no_response = None
                ctrl.cmd_ping.cancel()
                ctrl.cmd_ping = None

    def _wait_until_controllers_up(self):
        """Wait until all controllers stand up.

        :return: None but call itself until all controllers stand up.
        """
        for ctrl in self._ctrls:
            if ctrl.is_down:
                wait = True
                break
        else:
            wait = False
        if wait:
            MolerTest.sleep(self.recheck_time)
            self._wait_until_controllers_up()

    def _set_controller_to_down(self, ctrl):
        """Set controller status to down and start serdes reenabled observer.

        :param ctrl: Controller whose event call this method.
        :return: None
        """
        ctrl.is_down = True
        if ctrl.connection_type == "telnet":
            self._start_serdes_reenabled_observer(ctrl)
        elif ctrl.connection_type == "ssh":
            self._start_ping_response_observer(ctrl)

    def _start_serdes_reenabled_observer(self, ctrl):
        """Start serdes reenabled observer.

        :param ctrl: Controller on which event will be observed.
        :return: None but start serdes reenabled observer
        """
        ctrl.serdes_reenabled = ctrl.device.get_event(event_name="serdes_reenabled",
                                                      event_params={"till_occurs_times": 1})
        ctrl.serdes_reenabled.add_event_occurred_callback(callback=self._set_controller_to_up,
                                                          callback_params={'ctrl': ctrl})
        ctrl.serdes_reenabled.start(timeout=600)

    def _start_ping_response_observer(self, ctrl):
        """Start ping response observer.

        :param ctrl: Controller on which event will be observed.
        :return: None but start ping response observer
        """
        ctrl.ping_response = self._workstation.device.get_event(event_name="ping_response",
                                                                event_params={"till_occurs_times": 1})
        ctrl.ping_response.add_event_occurred_callback(callback=self._set_controller_to_up,
                                                       callback_params={'ctrl': ctrl})
        ctrl.ping_response.start(timeout=600)

    def _set_controller_to_up(self, ctrl):
        """Set controller status to up.

        :param ctrl: Controller whose event call this method.
        :return: None
        """
        ctrl.is_down = False
        ctrl.serdes_reenabled = None
        ctrl.ping_response = None


class ControllerRebootUtil(object):
    """Class containing utils to reboot controller."""
    def __init__(self, controller):
        """Controller Reboot Util.

        :param controller: Controller --> should be class of taf.ul.sc.rtg.controller.Controller
        """
        self.controller = controller
        self.device = controller.device
        self.connection_type = controller.connection_type
        self.host = controller.host if self.connection_type == 'ssh' else None
        self.stopping_session = None
        self.serdes_reenabled = None
        self.cmd_ping = None
        self.ping_no_response = None
        self.ping_response = None
        self.is_down = False
